window.FX=(()=>{const root=document.getElementById('touch-effects');function burst(x,y,amount=15){for(let i=0;i<amount;i++){let s=document.createElement('span');s.className='burst';s.textContent=['✦','✧','·','♡'][i%4];s.style.left=x+'px';s.style.top=y+'px';s.style.setProperty('--dx',(Math.random()*180-90)+'px');s.style.setProperty('--dy',(Math.random()*-140+20)+'px');s.style.animationDelay=(Math.random()*.1)+'s';root.append(s);setTimeout(()=>s.remove(),1200)}}function confetti(){for(let i=0;i<36;i++)burst(Math.random()*innerWidth,Math.random()*innerHeight*.6,1)}let toastTimer;function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2100)}document.addEventListener('pointerdown',e=>{if(e.target.closest('button'))burst(e.clientX,e.clientY,5)},{passive:true});return{burst,confetti,toast}})();
